const items = $input.all();
const rawInput = items[0]?.json?.body || items[0]?.json || {};

if (rawInput.topic === undefined || rawInput.topic === null) {
  throw new Error('Validation Error: Missing required field "topic".');
}

if (typeof rawInput.topic !== 'string') {
  throw new Error('Validation Error: "topic" must be a string.');
}

const topic = rawInput.topic.trim();
if (topic.length < 3 || topic.length > 250) {
  throw new Error(`Validation Error: "topic" length must be between 3 and 250 characters (received ${topic.length}).`);
}

let country = 'in';
if (rawInput.country !== undefined && rawInput.country !== null) {
  if (typeof rawInput.country !== 'string') {
    throw new Error('Validation Error: "country" must be a 2-letter ISO country code string.');
  }
  const cleanCountry = rawInput.country.trim().toLowerCase();
  if (!/^[a-z]{2}$/.test(cleanCountry)) {
    throw new Error(`Validation Error: "country" must be a valid 2-letter ISO code (e.g. "in", "us"). Received: "${rawInput.country}".`);
  }
  country = cleanCountry;
}

let language = 'en';
if (rawInput.language !== undefined && rawInput.language !== null) {
  if (typeof rawInput.language !== 'string') {
    throw new Error('Validation Error: "language" must be a valid ISO language code string.');
  }
  const cleanLanguage = rawInput.language.trim().toLowerCase();
  if (!/^[a-z]{2}(-[a-z]{2})?$/.test(cleanLanguage)) {
    throw new Error(`Validation Error: "language" must be a valid language code (e.g. "en", "hi"). Received: "${rawInput.language}".`);
  }
  language = cleanLanguage;
}

return [{
  json: {
    topic,
    country,
    language,
    validatedAt: new Date().toISOString()
  }
}];

const inputItem = $input.first()?.json || {};
const validatedItem = $('Validate Input').first()?.json || {};

const topic = validatedItem.topic || inputItem.search_parameters?.q || 'Unknown Topic';
const country = validatedItem.country || inputItem.search_parameters?.gl || 'in';
const language = validatedItem.language || inputItem.search_parameters?.hl || 'en';

function normalizeUrl(rawUrl) {
  if (!rawUrl || typeof rawUrl !== 'string') return null;
  var str = rawUrl.trim();
  if (!/^https?:\/\//i.test(str)) return null;

  var clean = str.split('#')[0];
  var qIndex = clean.indexOf('?');
  if (qIndex === -1) {
    return clean.replace(/\/+$/, '');
  }

  var baseUrl = clean.slice(0, qIndex).replace(/\/+$/, '');
  var queryStr = clean.slice(qIndex + 1);
  var tracking = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'gclid', 'fbclid', 'ref', 'ocid', 'mc_cid', 'mc_eid', '_hsenc', '_hsmi'];

  var keptParams = [];
  var pairs = queryStr.split('&');
  for (var i = 0; i < pairs.length; i++) {
    var pair = pairs[i];
    if (!pair) continue;
    var key = pair.split('=')[0].toLowerCase();
    if (tracking.indexOf(key) === -1) {
      keptParams.push(pair);
    }
  }

  return keptParams.length > 0 ? (baseUrl + '?' + keptParams.join('&')) : baseUrl;
}

const rawResults = inputItem.organic_results || [];

if (!Array.isArray(rawResults) || rawResults.length === 0) {
  return [{
    json: {
      success: true,
      topic,
      engine: 'google',
      sourceCount: 0,
      sources: [],
      metadata: {
        searchId: inputItem.search_metadata?.id || null,
        totalResults: 0,
        timeTakenSeconds: inputItem.search_metadata?.total_time_taken || 0,
        searchParameters: { engine: 'google', country, language },
        processedAt: new Date().toISOString()
      },
      limitations: [
        'Search snippets are preliminary evidence.',
        'Full documents have not necessarily been retrieved or verified.'
      ]
    }
  }];
}

const normalizedMap = new Map();

for (const r of rawResults) {
  const normUrl = normalizeUrl(r.link);
  if (!normUrl) continue;

  const title = typeof r.title === 'string' ? r.title.trim() : '';
  const snippet = typeof r.snippet === 'string' ? r.snippet.trim() : '';
  const pubDate = r.date || null;
  const displayedLink = r.displayed_link || null;
  const position = typeof r.position === 'number' ? r.position : null;

  const score = snippet.length + title.length + (pubDate ? 50 : 0) + (displayedLink ? 10 : 0);

  const candidate = {
    engine: 'google',
    title,
    url: r.link,
    snippet,
    displayedLink,
    publicationDate: pubDate,
    position,
    _score: score,
    metadata: {
      source: r.source || null,
      displayedLink: r.displayed_link || null,
      favicon: r.favicon || null
    }
  };

  if (!normalizedMap.has(normUrl) || normalizedMap.get(normUrl)._score < score) {
    normalizedMap.set(normUrl, candidate);
  }
}

const sources = Array.from(normalizedMap.values()).map((item, idx) => {
  const sourceId = 'S' + String(idx + 1).padStart(3, '0');
  delete item._score;
  return {
    sourceId,
    ...item
  };
});

const metadata = {
  searchId: inputItem.search_metadata?.id || null,
  totalResults: inputItem.search_information?.total_results || sources.length,
  timeTakenSeconds: inputItem.search_metadata?.total_time_taken || null,
  searchParameters: {
    engine: 'google',
    country,
    language
  },
  processedAt: new Date().toISOString()
};

return [{
  json: {
    success: true,
    topic,
    engine: 'google',
    sourceCount: sources.length,
    sources,
    metadata,
    limitations: [
      'Search snippets are preliminary evidence.',
      'Full documents have not necessarily been retrieved or verified.'
    ]
  }
}];

const raw = $input.first()?.json || {};
const errorMsg = typeof raw.error === 'string'
  ? raw.error
  : (raw.error?.message || raw.message || 'Validation Error: Invalid input parameters.');
const cleanMsg = errorMsg.replace(/\s*\[line\s+\d+\]$/, '').replace(/^Error:\s*/, '');

return [{
  json: {
    success: false,
    error: {
      code: 'INVALID_INPUT',
      message: cleanMsg,
      details: 'Topic must be a non-empty string between 3 and 250 characters. Country and language must be valid ISO codes.'
    },
    limitations: [
      'Request rejected before external search execution.'
    ]
  }
}];

const raw = $input.first()?.json || {};
const errorMsg = typeof raw.error === 'string'
  ? raw.error
  : (raw.error?.message || raw.message || 'SerpApi search request failed.');
const status = raw.error?.httpCode || raw.error?.statusCode || raw.httpCode || 502;

return [{
  json: {
    success: false,
    error: {
      code: 'UPSTREAM_SEARCH_ERROR',
      message: 'Failed to retrieve results from search provider.',
      upstreamStatus: status,
      details: errorMsg
    },
    limitations: [
      'Upstream search service unavailable or returned an error.'
    ]
  }
}];
